/** Locale-independent ordering used only by the prospective I -> P -> E evidence transition. */
export function judgeDemoInvocationIntegrityEvidencePathCompare(
  left: string,
  right: string
): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

