function impactExecutionUniqueIndex(source: string, token: string, label: string): number {
  const first = source.indexOf(token);
  if (first < 0 || source.indexOf(token, first + token.length) >= 0) {
    throw new Error(`impact_execution_judge_template_invalid:${label}`);
  }
  return first;
}

function impactExecutionIndent(source: string, prefix: string): string {
  return source
    .split("\n")
    .map((line) => (line.length === 0 ? line : `${prefix}${line}`))
    .join("\n");
}

export function applyImpactExecutionJudgeDiagnosticsPresentation(source: string): string {
  const introStartToken = `      <p>
        The server accepts no prompt, model, schema, URL, or tool choice from this page.`;
  const buttonStartToken = `      <div className="button-row">
        <button className="button button-primary"`;
  const noticesStartToken = "      {!runtimeBinding ? (\n";
  const statusStartToken = `      <div
        ref={statusFocus}
        className="runtime-receipt"`;
  const sectionEndToken = "    </section>\n  );\n";
  const introStart = impactExecutionUniqueIndex(source, introStartToken, "intro-start");
  const buttonStart = impactExecutionUniqueIndex(source, buttonStartToken, "button-start");
  const noticesStart = impactExecutionUniqueIndex(source, noticesStartToken, "notices-start");
  const statusStart = impactExecutionUniqueIndex(source, statusStartToken, "status-start");
  const sectionEnd = impactExecutionUniqueIndex(source, sectionEndToken, "section-end");
  if (!(introStart < buttonStart && buttonStart < noticesStart && noticesStart < statusStart)) {
    throw new Error("impact_execution_judge_template_invalid:order");
  }

  const intro = source.slice(introStart, buttonStart);
  const buttonBlock = source.slice(buttonStart, noticesStart);
  const notices = source.slice(noticesStart, statusStart);
  const status = source.slice(statusStart, sectionEnd);
  const buttonOpen = '      <div className="button-row">\n';
  const buttonClose = "      </div>\n\n";
  if (!buttonBlock.startsWith(buttonOpen) || !buttonBlock.endsWith(buttonClose)) {
    throw new Error("impact_execution_judge_template_invalid:button-frame");
  }
  const primaryEndToken = "        </button>\n";
  const primaryEnd = buttonBlock.indexOf(primaryEndToken);
  if (primaryEnd < 0 || buttonBlock.indexOf(primaryEndToken, primaryEnd + 1) < 0) {
    throw new Error("impact_execution_judge_template_invalid:button-cardinality");
  }
  const primary = buttonBlock.slice(buttonOpen.length, primaryEnd + primaryEndToken.length);
  const secondary = buttonBlock.slice(
    primaryEnd + primaryEndToken.length,
    buttonBlock.length - buttonClose.length
  );
  const rawStatus = status.replace("        ref={statusFocus}\n", "");
  if (rawStatus === status) {
    throw new Error("impact_execution_judge_template_invalid:status-ref");
  }
  const detailedIntro = impactExecutionIndent(intro, "    ")
    .replace(
      "            The server accepts no prompt, model, schema, URL, or tool choice from this page. Its only\n            request is:",
      "            The server accepts no prompt, model, schema, URL, or tool choice from this page. Its\n            only request is:"
    )
    .replace(
      "            challenge-lifetime judge allocation. Afterward, the sealed decision remains available for\n            local native replay without another model call.",
      "            challenge-lifetime judge allocation. Afterward, the sealed decision remains available\n            for local native replay without another model call."
    );
  const detailedStatus = impactExecutionIndent(rawStatus, "    ").replace(
    `          <div
            className="runtime-receipt"
            role="status"
            aria-live="polite"
            tabIndex={-1}
          >`,
    '          <div className="runtime-receipt" role="group">'
  );

  const presentation = `${JUDGE_DEMO_IMPACT_EXECUTION_JUDGE_DIAGNOSTICS_MARKER}      <div className="button-row judge-primary-action">
${primary}      </div>

${notices}      <div
        ref={statusFocus}
        className={error ? "judge-status-summary error-text" : "judge-status-summary"}
        role={error ? "alert" : "status"}
        aria-live={error ? "assertive" : "polite"}
        tabIndex={-1}
      >
        <strong>
          {running ? "running" : loading ? "checking" : (status?.status ?? "unavailable")}
        </strong>
        <span>{error ?? status?.reason ?? phase}</span>
      </div>

      <details className="judge-diagnostics">
        <summary>${JUDGE_DEMO_IMPACT_EXECUTION_JUDGE_DIAGNOSTICS_SUMMARY}</summary>
        <div className="judge-diagnostics-content">
${detailedIntro}          <div className="button-row">
${impactExecutionIndent(secondary, "    ")}          </div>

${detailedStatus}        </div>
      </details>
`;
  return `${source.slice(0, introStart)}${presentation}${source.slice(sectionEnd)}`;
}

